private InputStream createUtf8Input(final byte[] baseData, final boolean addBOM)  {
    byte[] data = baseData;
    if (addBOM)
    {
        data = new byte[baseData.length + 3];
        data[0] = (byte) 0xEF;
        data[1] = (byte) 0xBB;
        data[2] = (byte) 0xBF;
        System.arraycopy(baseData, 0, data, 3, baseData.length);
    }
    return new ByteArrayInputStream(data);
}
