public int read(final byte[] b, final int offset, final int length)  {
    if (b == null)
    {
        throw new NullPointerException();
    }
    if (offset < 0 || length < 0 || length > b.length - offset)
    {
        throw new IndexOutOfBoundsException( String.format("Range [%d, %<d + %d) out of bounds for length %d", offset, length, b.length));
    }
    if (length == 0)
    {
        return 0;
    }
    final List<Integer> drain = new ArrayList<>(Math.min(length, blockingQueue.size()));
    blockingQueue.drainTo(drain, length);
    if (drain.isEmpty())
    {
        // no data immediately available. wait for first byte final int value = read();
        if (value == EOF)
        {
            return EOF;
        }
        drain.add(value);
        blockingQueue.drainTo(drain, length - 1);
    }
    int i = 0;
    for (final Integer value : drain)
    {
        b[offset + i] = (byte) (0xFF & value);
        i++;
    }
    return i;
}
