void testBeanIntrospection() throws Exception  {
    final Uberspect uber = Engine.getUberspect(null, null);
    final Bean bean = new Bean("JEXL", "LXEJ");
    final JexlPropertyGet get = uber.getPropertyGet(bean, "value");
    final JexlPropertySet set = uber.getPropertySet(bean, "value", "foo");
    assertInstanceOf(PropertyGetExecutor.class, get, "bean property getter");
    assertInstanceOf(PropertySetExecutor.class, set, "bean property setter");
    // introspector and uberspect should return same result assertEquals(get, uber.getPropertyGet(bean, "value"));
    assertEquals(set, uber.getPropertySet(bean, "value", "foo"));
    // different property should return different setter/getter assertNotEquals(get, uber.getPropertyGet(bean, "eulav"));
    assertNotEquals(set, uber.getPropertySet(bean, "eulav", "foo"));
    // setter returns argument final Object bar = set.invoke(bean, "bar");
    assertEquals("bar", bar);
    // getter should return last value assertEquals("bar", get.invoke(bean));
    // tryExecute should succeed on same property final Object quux = set.tryInvoke(bean, "value", "quux");
    assertEquals("quux", quux);
    assertEquals("quux", get.invoke(bean));
    // tryExecute should fail on different property assertEquals(AbstractExecutor.TRY_FAILED, set.tryInvoke(bean, "eulav", "nope"));
}
