                    for (final Method method : methods)
                    {
                        final Class<?>[] parms = method.getParameterTypes();
                        if (parms.length != op.getArity())
                        {
                            continue;
                        }
                        // filter method that is an actual overload: // - not inherited (not declared by base class) // - nor overridden (not present in base class) if (!JexlArithmetic.class.equals(method.getDeclaringClass()))
